#include "dfre/mission_event_markers.hpp"
#include <iostream>
#include <stdexcept>
#include <vector>
using U=std::uint32_t;using Q=std::uint64_t;
constexpr U E=0x1300100,T=0x1301000,A=0x1302000,ALT=0x1303000,D=0x1304000,M=0x8ace80;
struct Region{U at;std::vector<unsigned char> bytes;};
int main(){U op,seed,mutation,fault;while(std::cin>>op>>seed>>mutation>>fault){std::vector<Region> regions;for(auto x:std::vector<std::pair<U,U>>{{0x4f2bc8,32},{0x1300000,0x5000},{M,4*0x114},{0x8cf900,4}})regions.push_back({x.first,std::vector<unsigned char>(x.second,static_cast<unsigned char>(seed))});auto byte=[&](U at)->unsigned char&{for(auto& r:regions)if(at>=r.at&&Q(at)-r.at<r.bytes.size())return r.bytes[at-r.at];throw std::runtime_error("Unmapped marker fixture");};auto get=[&](U at,unsigned w){U v=0;for(U i=0;i<w;++i)v|=U(byte(at+i))<<(i*8);return v;};auto put=[&](U at,unsigned w,U v){for(U i=0;i<w;++i)byte(at+i)=static_cast<unsigned char>(v>>(i*8));};
 put(0x4f2bcc,4,E);put(0x4f2bc8,4,seed%13==0?0:seed%17==0?0xffffffffu:2);put(0x8cf900,4,seed%11==0?0:seed%19==0?0xffffffffu:4);
 for(U i=0;i<2;++i){put(E+i*24+4,4,T+i*128);put(E+i*24+8,4,A+i*128);put(E+i*24+21,1,2);put(E+i*24+22,1,2);}
 for(U base:{T,A,ALT})for(U i=0;i<8;++i){put(base+i*32+4,4,base==T?(i%3==2?0:1):(i%3==2?0:i%2?13:12));put(base+i*32+8,4,base==T?10:0);put(base+i*32+12,4,7);put(base+i*32+16,4,7);}
 if(seed%23==0){put(E+4,4,0);put(E+8,4,0);}for(U i=0;i<4;++i){put(M+i*0x114+4,4,seed%7==0&&i==0?0:D+i*64);put(D+i*64+0x20,4,seed%5==0&&i==1?0:0x177d);put(M+i*0x114+0x7c,4,seed%3==0&&i==2?8:7);put(M+i*0x114+0x24,4,i==0?0x80000000u+i:seed*17+i*31);put(M+i*0x114+0x28,4,i==0?0x7fffffffu:0u-seed*19-i*37);}
 Q trace=1469598103934665603ull;U entries=0,operations=0;bool read_mutated=false,write_mutated=false;auto emit=[&](U kind,U at,U w,U v){++entries;for(U x:{kind,at,w,v})for(U i=0;i<4;++i)trace=(trace^((x>>(i*8))&255))*1099511628211ull;};auto stop=[&](){if(fault&&++operations==fault)throw std::runtime_error("Injected marker fault");};auto read_effect=[&](U at){if(!read_mutated&&at==M+0x7c){read_mutated=true;if(mutation&1)put(E+(op?8:4),4,ALT);if(mutation&8)put(0x8cf900,4,1);}if(at==M+0x24&&(mutation&4))put(M+0x28,4,0x87654321);if(at==E+(op?22:21)&&(mutation&32))put(0x4f2bc8,4,0);};auto write_effect=[&](){if(!write_mutated){write_mutated=true;if(mutation&2){put(0x4f2bcc,4,E+24);put(0x4f2bc8,4,1);put(E+(op?22:21),1,2);}if(mutation&16)put(E+(op?8:4),4,ALT+32);if(mutation&64)put(M+0x7c,4,8);}};
 dfre::MissionEventResourceBindings b;b.read=[&](U at,unsigned w){const U value=get(at,w);emit('R',at,w,value);read_effect(at);stop();return value;};b.write=[&](U at,unsigned w,U v){put(at,w,v);emit('W',at,w,v);write_effect();stop();};bool failed=false;try{if(op)dfre::mission_event_markers_actions(b);else dfre::mission_event_markers_triggers(b);}catch(const std::exception&){failed=true;}Q digest=1469598103934665603ull;for(auto& r:regions)for(auto v:r.bytes)digest=(digest^v)*1099511628211ull;std::cout<<failed<<' '<<digest<<' '<<trace<<' '<<entries<<'\n';}}
